function _quadrature_table(::Type{BigFloat}, rows::Vector{Vector{String}})
    return setprecision(BigFloat, 288) do
        [BigFloat[parse(BigFloat, s) for s in row] for row in rows]
    end
end

function _quadrature_table(::Type{T}, rows::Vector{Vector{String}}) where {T}
    return [T.(row) for row in _quadrature_table(BigFloat, rows)]
end

_gauss_tables(::Type{Float64}) = (gauss_points, gauss_weights)
function _gauss_tables(::Type{T}) where {T}
    return (
        _quadrature_table(T, _GAUSS_POINTS_STR),
        _quadrature_table(T, _GAUSS_WEIGHTS_STR),
    )
end

_gk_tables(::Type{Float64}) = (gk_points, gk_weights, g_weights)
function _gk_tables(::Type{T}) where {T}
    return (
        _quadrature_table(T, _GK_POINTS_STR),
        _quadrature_table(T, _GK_WEIGHTS_STR),
        _quadrature_table(T, _G_WEIGHTS_STR),
    )
end

function _quadrature_eltype(integrand_el::Type, time_el::Type, prototype_el::Type)
    T = promote_type(real(integrand_el), real(time_el), real(prototype_el))
    return T <: AbstractFloat ? T : Float64
end

function _quadrature_eltype(integrand_el::Type, prototype_el::Type)
    T = promote_type(real(integrand_el), real(prototype_el))
    return T <: AbstractFloat ? T : Float64
end
